import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.context.annotation.ComponentScan;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.EnableAspectJAutoProxy;

// ====== 场景：同类 this 调用导致 @Transactional 失效 ======

@Service
public class OrderService {

    // 外部入口：经过代理，事务生效
    @Transactional
    public void placeOrder() {
        // 写库操作
        System.out.println("[placeOrder] insert order, tx active="
                + org.springframework.transaction.support.TransactionSynchronizationManager
                .isActualTransactionActive());
        // this 调用：不经过代理，cancel() 上的 @Transactional 失效
        this.cancelOrder();
    }

    @Transactional
    public void cancelOrder() {
        System.out.println("[cancelOrder] tx active="
                + org.springframework.transaction.support.TransactionSynchronizationManager
                .isActualTransactionActive());
        // 期望：cancelOrder 有独立事务或共享事务
        // 实际（this 调用时）：tx active=false，事务失效
    }
}

@Configuration
@EnableAspectJAutoProxy(exposeProxy = true) // exposeProxy 允许 AopContext.currentProxy()
@ComponentScan
public class AppConfig {
}

public class Main {
    public static void main(String[] args) {
        var ctx = new AnnotationConfigApplicationContext(AppConfig.class);
        var service = ctx.getBean(OrderService.class);

        System.out.println("--- placeOrder（代理调用，事务生效）---");
        service.placeOrder();

        // 修复方案：通过 AopContext 获取代理对象调用
        System.out.println("\n--- 通过代理对象调用 cancelOrder ---");
        OrderService proxy = (OrderService) org.springframework.aop.framework.AopContext
                .currentProxy();
        proxy.cancelOrder();

        ctx.close();
    }
}
